content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: #0b0f19;
  color: #f3f4f6;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at center, #111827 0%, #030712 100%);
}

.canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 1;
  will-change: transform;
}

.controls-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 24px;
}

.control-panel {
  pointer-events: auto;
  background: rgba(17, 24, 39, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 20px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.control-group {
  margin-bottom: 16px;
}

.control-group:last-child {
  margin-bottom: 0;
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: #ffffff;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.hint {
  font-size: 0.875rem;
  color: #9ca3af;
  margin-bottom: 16px;
  line-height: 1.4;
}

.btn {
  background: rgba(31, 41, 55, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #d1d5db;
  padding: 8px 14px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:hover {
  background: rgba(55, 65, 81, 0.9);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
}

.btn:active {
  transform: scale(0.97);
}

.btn-active {
  background: #3b82f6;
  color: #ffffff;
  border-color: #60a5fa;
  box-shadow: 0 0 15px rgba(59, 130, 246, 0.5);
}

.btn-active:hover {
  background: #2563eb;
}

@media (max-width: 640px) {
  .controls-overlay {
    padding: 16px;
  }

  .control-panel {
    max-width: 100%;
    padding: 16px;
  }
}

import { useState, useEffect, useRef } from 'react';
import { Sparkles, RefreshCw, Layers, Palette, Eye, EyeOff } from 'lucide-react';

type ParticleMode = 'follow' | 'fireworks' | 'galaxy';
type ColorTheme = 'neon' | 'sunset' | 'aurora' | 'cyberpunk';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  life: number;
  maxLife: number;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [mode, setMode] = useState<ParticleMode>('follow');
  const [theme, setTheme] = useState<ColorTheme>('neon');
  const [showControls, setShowControls] = useState<boolean>(true);
  const [particleCount] = useState<number>(180);
  const [refreshKey, setRefreshKey] = useState<number>(0);

  const mouseRef = useRef({ x: window.innerWidth / 2, y: window.innerHeight / 2, isDown: false });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let particles: Particle[] = [];
    let lastWidth = window.innerWidth;
    let lastHeight = window.innerHeight;

    const getColors = (t: ColorTheme): string[] => {
      switch (t) {
        case 'sunset': return ['#ff7e5f', '#feb47b', '#ff6b6b', '#ffa07a', '#ffeaa7'];
        case 'aurora': return ['#00b4d8', '#90e0ef', '#0077b6', '#48cae4', '#ade8f4'];
        case 'cyberpunk': return ['#f72585', '#b5179e', '#7209b7', '#3a0ca3', '#4cc9f0'];
        case 'neon':
        default: return ['#3b82f6', '#60a5fa', '#9333ea', '#c084fc', '#f43f5e', '#10b981'];
      }
    };

    const createParticle = (x: number, y: number, customMode?: ParticleMode): Particle => {
      const colors = getColors(theme);
      const color = colors[Math.floor(Math.random() * colors.length)];
      const activeMode = customMode || mode;

      let maxLife = Math.random() * 60 + 40;

      if (activeMode === 'galaxy') {
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * 120 + 20;
        return {
          x: x + Math.cos(angle) * dist,
          y: y + Math.sin(angle) * dist,
          vx: -Math.sin(angle) * 2 + (Math.random() - 0.5),
          vy: Math.cos(angle) * 2 + (Math.random() - 0.5),
          size: Math.random() * 2 + 1,
          color,
          alpha: 1,
          life: 0,
          maxLife: maxLife * 1.5
        };
      } else if (activeMode === 'fireworks') {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 6 + 2;
        return {
          x,
          y,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          size: Math.random() * 3 + 2,
          color,
          alpha: 1,
          life: 0,
          maxLife: 50
        };
      }

      return {
        x,
        y,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        size: Math.random() * 3 + 1.5,
        color,
        alpha: 1,
        life: 0,
        maxLife
      };
    };

    const resize = () => {
      const dpr = window.devicePixelRatio || 1;
      const width = window.innerWidth;
      const height = window.innerHeight;

      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      if (particles.length > 0 && lastWidth > 0 && lastHeight > 0) {
        const scaleX = width / lastWidth;
        const scaleY = height / lastHeight;
        particles.forEach(p => {
          p.x *= scaleX;
          p.y *= scaleY;
        });
      }

      lastWidth = width;
      lastHeight = height;
    };

    resize();
    window.addEventListener('resize', resize);

    for (let i = 0; i < particleCount; i++) {
      particles.push(createParticle(Math.random() * lastWidth, Math.random() * lastHeight));
    }

    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current.x = e.clientX;
      mouseRef.current.y = e.clientY;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouseRef.current.x = e.touches[0].clientX;
        mouseRef.current.y = e.touches[0].clientY;
      }
    };

    const handleMouseDown = () => { mouseRef.current.isDown = true; };
    const handleMouseUp = () => { mouseRef.current.isDown = false; };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    const render = () => {
      ctx.fillStyle = 'rgba(11, 15, 25, 0.2)';
      ctx.fillRect(0, 0, lastWidth, lastHeight);

      const { x, y, isDown } = mouseRef.current;

      if (particles.length < particleCount) {
        particles.push(createParticle(x + (Math.random() - 0.5) * 20, y + (Math.random() - 0.5) * 20));
      }

      if (isDown) {
        for (let i = 0; i < 4; i++) {
          particles.push(createParticle(x, y, 'fireworks'));
        }
      }

      particles.forEach((p, index) => {
        p.life++;
        p.alpha = 1 - p.life / p.maxLife;

        if (mode === 'follow') {
          const dx = x - p.x;
          const dy = y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist > 1) {
            p.vx += (dx / dist) * 0.25;
            p.vy += (dy / dist) * 0.25;
          }
          p.vx *= 0.94;
          p.vy *= 0.94;
        } else if (mode === 'galaxy') {
          const dx = x - p.x;
          const dy = y - p.y;
          p.vx += dx * 0.005;
          p.vy += dy * 0.005;
          p.vx *= 0.92;
          p.vy *= 0.92;
        }

        p.x += p.vx;
        p.y += p.vy;

        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        if (p.life >= p.maxLife || p.x < 0 || p.x > lastWidth || p.y < 0 || p.y > lastHeight) {
          particles[index] = createParticle(x + (Math.random() - 0.5) * 60, y + (Math.random() - 0.5) * 60);
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      cancelAnimationFrame(animationFrameId);
    };
  }, [mode, theme, particleCount, refreshKey]);

  const resetParticles = () => {
    setRefreshKey((prev) => prev + 1);
  };

  return (
    <div className="app-container">
      <canvas ref={canvasRef} className="canvas" />

      <div className="controls-overlay">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', width: '100%' }}>
          <div>
            {showControls && (
              <div className="control-panel">
                <div className="title">
                  <Sparkles size={20} style={{ color: '#60a5fa' }} />
                  パーティクルアート
                </div>
                <div className="hint">
                  画面をマウスやタッチで動かしてパーティクルを誘導しよう。クリックで花火が爆発します。
                </div>

                <div className="control-group">
                  <div style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '8px', color: '#e5e7eb', display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <Layers size={16} /> 動作モード
                  </div>
                  <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                    <button 
                      className={`btn ${mode === 'follow' ? 'btn-active' : ''}`}
                      onClick={() => setMode('follow')}
                    >
                      追従
                    </button>
                    <button 
                      className={`btn ${mode === 'fireworks' ? 'btn-active' : ''}`}
                      onClick={() => setMode('fireworks')}
                    >
                      花火
                    </button>
                    <button 
                      className={`btn ${mode === 'galaxy' ? 'btn-active' : ''}`}
                      onClick={() => setMode('galaxy')}
                    >
                      ギャラクシー
                    </button>
                  </div>
                </div>

                <div className="control-group">
                  <div style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '8px', color: '#e5e7eb', display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <Palette size={16} /> カラーテーマ
                  </div>
                  <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                    <button 
                      className={`btn ${theme === 'neon' ? 'btn-active' : ''}`}
                      onClick={() => setTheme('neon')}
                    >
                      ネオン
                    </button>
                    <button 
                      className={`btn ${theme === 'sunset' ? 'btn-active' : ''}`}
                      onClick={() => setTheme('sunset')}
                    >
                      サンセット
                    </button>
                    <button 
                      className={`btn ${theme === 'aurora' ? 'btn-active' : ''}`}
                      onClick={() => setTheme('aurora')}
                    >
                      オーロラ
                    </button>
                    <button 
                      className={`btn ${theme === 'cyberpunk' ? 'btn-active' : ''}`}
                      onClick={() => setTheme('cyberpunk')}
                    >
                      サイバー
                    </button>
                  </div>
                </div>

                <div className="control-group" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '16px' }}>
                  <button className="btn" onClick={resetParticles} style={{ width: '100%' }}>
                    <RefreshCw size={14} /> リフレッシュ
                  </button>
                </div>
              </div>
            )}
          </div>

          <button 
            className="btn" 
            onClick={() => setShowControls(!showControls)}
            style={{ pointerEvents: 'auto', background: 'rgba(17, 24, 39, 0.8)' }}
          >
            {showControls ? <EyeOff size={16} /> : <Eye size={16} />}
            {showControls ? 'UIを隠す' : 'UIを表示'}
          </button>
        </div>

        <div style={{ pointerEvents: 'auto', textAlign: 'center', fontSize: '0.75rem', color: '#6b7280' }}>
          Interactive Particle Simulation powered by React & HTML5 Canvas
        </div>
      </div>
    </div>
  );
}
